 case 'FontStyleSelect':{const fs=st.fontStyle===FontStyle.Undefined?FontStyle.Normal:st.fontStyle;return h('span',{class:'es-button-row','data-name':w.n},([[FontStyle.Bold,ICON_CODES.TEXT_BOLD,'Bold'],[FontStyle.Italic,ICON_CODES.TEXT_ITALIC,'Italic'],[FontStyle.Underline,ICON_CODES.TEXT_UNDERLINE,'Underline'],[FontStyle.Strike,ICON_CODES.TEXT_STRIKE,'Strike']] as const).map(([flag,code,label])=>h('button',{type:'button',class:['es-toggle',(fs&flag)!==0&&'checked'],disabled:dis,title:qtrc('FontStyleSelect',label),'aria-label':qtrc('FontStyleSelect',label),'aria-pressed':(fs&flag)!==0,onClick:()=>{es.setFontStyle(w.n,((fs&flag)?fs&~flag:fs|flag) as FontStyle);changed()}},String.fromCodePoint(code))))}
