</script>
<template>
 <dialog v-if="model" ref="dialog" class="edit-style" aria-labelledby="edit-style-title" @cancel.prevent="close(false)" @keydown.enter="($event.target as HTMLElement).tagName !== 'BUTTON' && $event.preventDefault()"><h2 id="edit-style-title">{{tr('Style')}}</h2><div class="es-main"><div v-if="pageList" class="es-pagelist" role="listbox" :aria-label="tr('Style')"><div v-for="(item,i) in pages" :key="i" role="option" :class="{selected:i===current}" :aria-selected="i===current" @click="choosePage(i)">{{text(item)}}</div></div><div :key="current" class="es-page"><component :is="renderPage()" /></div></div><div class="dialog-buttons es-buttons"><button type="button" class="secondary es-toggle-pagelist" aria-label="toggle page list" @click="togglePageList">{{String.fromCodePoint(pageList?ICON_CODES.ARROW_RIGHT:ICON_CODES.ARROW_LEFT)}}</button><button type="button" class="secondary" @click="model.click('resetStylesButton');changed()">{{tr('Reset all styles to default')}}</button><span class="spacer" /><button v-if="model.canApplyToAllParts()" type="button" class="secondary" @click="model.applyToAllParts();changed()">{{qtrc('notation/editstyle','Apply to all parts')}}</button><button type="button" class="secondary" @click="close(false)">{{qtrc('global','Cancel')}}</button><button type="button" class="primary" @click="close(true)">{{qtrc('global','OK')}}</button></div></dialog>
</template>
